public class Ex11 {
    static class Bean {
        void init() { System.out.println("[init] bean initialized"); }
        void destroy() { System.out.println("[destroy] bean cleaned up"); }
        void use() { System.out.println("[use] bean working"); }
    }
    public static void main(String[] args) {
        Bean b = new Bean();
        // 容器在实例化后回调 init，关闭时回调 destroy
        b.init();
        b.use();
        b.destroy();
    }
}
